<main id="main" class="main">
    <div class="pagetitle admin-message-page-heading"><div><p class="admin-eyebrow">Communication institutionnelle</p><h1>Messages reçus</h1><p>Retrouvez les demandes envoyées depuis le formulaire public et lisez leur contenu complet.</p></div><div class="admin-message-total"><i class="bi bi-inbox" aria-hidden="true"></i><span><strong><?= number_format($messageTotalCount, 0, ',', ' ') ?></strong><small><?= $messageTotalCount === 1 ? 'message reçu' : 'messages reçus' ?></small><span class="admin-message-unread-total"><i class="bi bi-envelope-exclamation" aria-hidden="true"></i><?= number_format($messageUnreadCount, 0, ',', ' ') ?> non lu<?= $messageUnreadCount === 1 ? '' : 's' ?></span></span></div></div>
    <section class="section admin-message-inbox" aria-label="Boîte de réception">
        <div class="card admin-message-search-card"><div class="card-body">
            <form method="get" class="admin-message-search"><input type="hidden" name="pages" value="messagerie"><?php if ($messageFilter !== 'all'): ?><input type="hidden" name="etat" value="<?= htmlspecialchars($messageFilter, ENT_QUOTES, 'UTF-8') ?>"><?php endif; ?><label for="message-search"><i class="bi bi-search" aria-hidden="true"></i><span class="visually-hidden">Rechercher dans les messages</span></label><input class="form-control" id="message-search" name="q" value="<?= htmlspecialchars($messageSearch, ENT_QUOTES, 'UTF-8') ?>" placeholder="Rechercher par nom, e-mail, sujet ou contenu"><button class="btn btn-primary" type="submit">Rechercher</button><?php if ($messageSearch !== ''): ?><a class="btn btn-outline-secondary" href="?pages=messagerie<?= $messageFilter !== 'all' ? '&amp;etat=' . rawurlencode($messageFilter) : '' ?>"><i class="bi bi-x-lg me-1" aria-hidden="true"></i>Effacer</a><?php endif; ?></form>
            <nav class="admin-message-filters" aria-label="Filtrer les messages par état">
                <a class="<?= $messageFilter === 'all' ? 'active' : '' ?>" href="?pages=messagerie<?= $messageSearch !== '' ? '&amp;q=' . rawurlencode($messageSearch) : '' ?>" <?= $messageFilter === 'all' ? 'aria-current="page"' : '' ?>>Tous <span><?= number_format($messageTotalCount, 0, ',', ' ') ?></span></a>
                <a class="<?= $messageFilter === 'unread' ? 'active' : '' ?>" href="?pages=messagerie&amp;etat=unread<?= $messageSearch !== '' ? '&amp;q=' . rawurlencode($messageSearch) : '' ?>" <?= $messageFilter === 'unread' ? 'aria-current="page"' : '' ?>>Non lus <span><?= number_format($messageUnreadCount, 0, ',', ' ') ?></span></a>
                <a class="<?= $messageFilter === 'read' ? 'active' : '' ?>" href="?pages=messagerie&amp;etat=read<?= $messageSearch !== '' ? '&amp;q=' . rawurlencode($messageSearch) : '' ?>" <?= $messageFilter === 'read' ? 'aria-current="page"' : '' ?>>Lus <span><?= number_format(max(0, $messageTotalCount - $messageUnreadCount), 0, ',', ' ') ?></span></a>
            </nav>
            <div class="admin-message-list-heading"><h2><i class="bi bi-envelope-paper" aria-hidden="true"></i> Boîte de réception</h2><span><?= $messageCount > 0 ? number_format(min($messageCount, $messageOffset + 1), 0, ',', ' ') . '–' . number_format(min($messageCount, $messageOffset + count($contactMessages)), 0, ',', ' ') . ' sur ' . number_format($messageCount, 0, ',', ' ') : 'Aucun résultat' ?></span></div>
            <?php if ($contactMessages): ?>
                <div class="admin-message-list">
                    <?php foreach ($contactMessages as $message):
                        $senderName = trim((string) $message['name']);
                        $senderParts = preg_split('/\s+/u', $senderName) ?: [];
                        $initials = mb_strtoupper(mb_substr($senderParts[0] ?? '?', 0, 1, 'UTF-8') . (count($senderParts) > 1 ? mb_substr($senderParts[count($senderParts) - 1], 0, 1, 'UTF-8') : ''), 'UTF-8');
                        $messageText = trim((string) $message['message']);
                        $messagePreview = mb_strimwidth((string) preg_replace('/\s+/u', ' ', strip_tags($messageText)), 0, 190, '…', 'UTF-8');
                        $messageSubject = trim((string) $message['subject']);
                        $isMessageRead = (int) $message['is_read'] === 1;
                    ?>
                        <article class="admin-message-card<?= $isMessageRead ? ' is-read' : ' is-unread' ?>">
                            <div class="admin-message-person"><span class="admin-message-avatar" aria-hidden="true"><?= htmlspecialchars($initials, ENT_QUOTES, 'UTF-8') ?></span><div class="admin-message-sender"><strong><?= htmlspecialchars($senderName, ENT_QUOTES, 'UTF-8') ?></strong><a href="mailto:<?= htmlspecialchars((string) $message['email'], ENT_QUOTES, 'UTF-8') ?>"><?= htmlspecialchars((string) $message['email'], ENT_QUOTES, 'UTF-8') ?></a></div><span class="admin-message-state <?= $isMessageRead ? 'state-read' : 'state-unread' ?>"><i class="bi bi-<?= $isMessageRead ? 'envelope-open' : 'envelope-exclamation' ?>" aria-hidden="true"></i><?= $isMessageRead ? 'Lu' : 'Non lu' ?></span><a class="admin-message-reply" href="mailto:<?= htmlspecialchars((string) $message['email'], ENT_QUOTES, 'UTF-8') ?>" aria-label="Répondre à <?= htmlspecialchars($senderName, ENT_QUOTES, 'UTF-8') ?>"><i class="bi bi-reply-fill" aria-hidden="true"></i><span>Répondre</span></a></div>
                            <div class="admin-message-content"><p class="admin-message-subject-label">Objet du message</p><h3><?= htmlspecialchars($messageSubject !== '' ? $messageSubject : 'Sans objet', ENT_QUOTES, 'UTF-8') ?></h3>
                                <details class="admin-message-details"><summary><span class="admin-message-preview"><?= htmlspecialchars($messagePreview !== '' ? $messagePreview : 'Ce message ne contient pas de texte.', ENT_QUOTES, 'UTF-8') ?></span><span class="admin-message-read"><span class="admin-message-read-closed">Lire le message</span><span class="admin-message-read-open">Réduire</span><i class="bi bi-chevron-down" aria-hidden="true"></i></span></summary><div class="admin-message-full"><?= $messageText !== '' ? admin_contact_message_preview_html($messageText) : '<span class="text-muted">Ce message ne contient pas de texte.</span>' ?></div></details>
                            </div>
                            <div class="admin-message-actions"><span class="admin-message-channel"><i class="bi bi-envelope" aria-hidden="true"></i> Formulaire du site</span><div class="admin-message-actions-right"><form method="post"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(csrf_token(), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="record_id" value="<?= (int) $message['id'] ?>"><input type="hidden" name="return_q" value="<?= htmlspecialchars($messageSearch, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="return_etat" value="<?= htmlspecialchars($messageFilter, ENT_QUOTES, 'UTF-8') ?>"><button class="btn btn-sm <?= $isMessageRead ? 'btn-outline-secondary' : 'btn-outline-primary' ?>" type="submit" name="admin_action" value="<?= $isMessageRead ? 'mark_unread' : 'mark_read' ?>"><i class="bi bi-<?= $isMessageRead ? 'envelope' : 'envelope-open' ?> me-1" aria-hidden="true"></i>Marquer comme <?= $isMessageRead ? 'non lu' : 'lu' ?></button></form><form method="post" onsubmit="return confirm('Supprimer définitivement ce message ?');"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(csrf_token(), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="record_id" value="<?= (int) $message['id'] ?>"><button class="btn btn-sm btn-outline-danger" type="submit" name="admin_action" value="delete"><i class="bi bi-trash3 me-1" aria-hidden="true"></i> Supprimer</button></form></div></div>
                        </article>
                    <?php endforeach; ?>
                </div>
                <?php if ($messagePages > 1): ?><nav aria-label="Pagination des messages"><ul class="pagination flex-wrap">
                    <li class="page-item <?= $messagePage === 1 ? 'disabled' : '' ?>"><a class="page-link" href="?pages=messagerie&amp;pag=<?= max(1, $messagePage - 1) ?>&amp;q=<?= rawurlencode($messageSearch) ?><?= $messageFilter !== 'all' ? '&amp;etat=' . rawurlencode($messageFilter) : '' ?>" aria-label="Page précédente">Précédent</a></li>
                    <?php if ($messageWindowStart > 1): ?><li class="page-item"><a class="page-link" href="?pages=messagerie&amp;pag=1&amp;q=<?= rawurlencode($messageSearch) ?><?= $messageFilter !== 'all' ? '&amp;etat=' . rawurlencode($messageFilter) : '' ?>">1</a></li><?php if ($messageWindowStart > 2): ?><li class="page-item disabled"><span class="page-link">…</span></li><?php endif; ?><?php endif; ?>
                    <?php for ($p = $messageWindowStart; $p <= $messageWindowEnd; $p++): ?><li class="page-item <?= $p === $messagePage ? 'active' : '' ?>"><a class="page-link" href="?pages=messagerie&amp;pag=<?= $p ?>&amp;q=<?= rawurlencode($messageSearch) ?><?= $messageFilter !== 'all' ? '&amp;etat=' . rawurlencode($messageFilter) : '' ?>" <?= $p === $messagePage ? 'aria-current="page"' : '' ?>><?= $p ?></a></li><?php endfor; ?>
                    <?php if ($messageWindowEnd < $messagePages): ?><?php if ($messageWindowEnd < $messagePages - 1): ?><li class="page-item disabled"><span class="page-link">…</span></li><?php endif; ?><li class="page-item"><a class="page-link" href="?pages=messagerie&amp;pag=<?= $messagePages ?>&amp;q=<?= rawurlencode($messageSearch) ?><?= $messageFilter !== 'all' ? '&amp;etat=' . rawurlencode($messageFilter) : '' ?>"><?= $messagePages ?></a></li><?php endif; ?>
                    <li class="page-item <?= $messagePage === $messagePages ? 'disabled' : '' ?>"><a class="page-link" href="?pages=messagerie&amp;pag=<?= min($messagePages, $messagePage + 1) ?>&amp;q=<?= rawurlencode($messageSearch) ?><?= $messageFilter !== 'all' ? '&amp;etat=' . rawurlencode($messageFilter) : '' ?>" aria-label="Page suivante">Suivant</a></li>
                </ul></nav><?php endif; ?>
            <?php else: ?><div class="admin-message-empty"><span><i class="bi bi-inbox" aria-hidden="true"></i></span><h3><?= $messageLoadError ? 'Boîte indisponible' : ($messageSearch !== '' || $messageFilter !== 'all' ? 'Aucun message trouvé' : 'Votre boîte est vide') ?></h3><p><?= $messageLoadError ? 'Appliquez la migration de suivi des messages pour activer la boîte de réception.' : ($messageSearch !== '' || $messageFilter !== 'all' ? 'Essayez un autre filtre ou un autre terme de recherche.' : 'Les demandes envoyées depuis le formulaire de contact apparaîtront ici.') ?></p><?php if (!$messageLoadError && ($messageSearch !== '' || $messageFilter !== 'all')): ?><a class="btn btn-outline-primary" href="?pages=messagerie">Afficher tous les messages</a><?php endif; ?></div><?php endif; ?>
        </div></div>
    </section>
</main>
